48	    @Test
49	    @DisplayName("恰10%直切+灰分恰2级：全流程直切，不占用清洗窗口，窗口边界参数合格")
50	    void directSwitchAtBoundaryFullFlow() {
51	        OrderView applied = service.apply(new ApplyOrderRequest(
52	                "req-direct-1", "PM-1", "G-A4-70", "G-A4-77")).data();
53	        assertEquals(TransitionStatus.APPLIED, applied.status());
54	
55	        OrderView decided = service.decide(applied.orderNo());
56	        assertEquals(0, new BigDecimal("10.0000").compareTo(decided.basisWeightDeltaPct()));
57	        assertEquals(2, decided.ashLevelDelta());
58	        assertTrue(decided.directSwitch(), "恰 10% 直切");
59	        assertFalse(decided.wireFlush(), "灰分恰 2 级不冲洗网部");
60	        assertEquals(TransitionStatus.DECIDED, decided.status());
61	
62	        // 新品种 G-A4-77 窗口车速 [820,1020]、浓度 [0.850,1.250]：恰下边界合格。
63	        OrderView executed = service.execute(applied.orderNo(), new ExecuteOrderRequest(
64	                new BigDecimal("820.000"), new BigDecimal("0.850"), 120));
65	        assertEquals(0, new BigDecimal("1640.000").compareTo(executed.transitionLengthM()),
66	                "820 m/min × 120 s / 60 = 1640 m");
67	        assertEquals(TransitionStatus.EXECUTED, executed.status());
68	        assertEquals(0L, jdbc.queryForObject(
69	                "SELECT COUNT(1) FROM cleaning_window WHERE order_no = ?",
70	                Long.class, applied.orderNo()), "直切不得登记清洗窗口");
71	
72	        OrderView disposed = service.dispose(applied.orderNo(), new DisposeRollsRequest(List.of(
73	                new DisposeRollsRequest.RollItem("R-DIRECT-1", new BigDecimal("800.000")),
74	                new DisposeRollsRequest.RollItem("R-DIRECT-2", new BigDecimal("840.000")))));
75	        assertEquals(TransitionStatus.DISPOSED, disposed.status());
76	
77	        RollView roll = service.getRoll("R-DIRECT-1");
78	        assertEquals("DOWNGRADED", roll.verdict(), "过渡卷强制降级");
79	        assertEquals("NON_GENUINE", roll.warehouseStatus(), "不得按正品入库");
80	        assertEquals(1, roll.chain().size());
81	        assertEquals("FORCED_DOWNGRADE", roll.chain().get(0).eventType());
82	
83	        OrderView completed = service.complete(applied.orderNo());
84	        assertEquals(TransitionStatus.COMPLETED, completed.status());
85	        // 完成后释放纸机，同机可再申请。
86	        OrderView next = service.apply(new ApplyOrderRequest(
87	                "req-direct-2", "PM-1", "G-A4-70", "G-A4-77")).data();
88	        assertNotNull(next.orderNo());
89	    }
