93	    void stopCleaningFlowOccupiesCleaningWindowAtomically() {
94	        OrderView applied = service.apply(new ApplyOrderRequest(
95	                "req-clean-1", "PM-2", "G-A4-70", "G-A4-80")).data();
96	        OrderView decided = service.decide(applied.orderNo());
97	        assertFalse(decided.directSwitch(), "克重差 14.29% 须停机清洗");
98	        assertTrue(decided.wireFlush(), "灰分差 3 级须冲洗网部");
99	
100	        // 恰在 G-A4-80 窗口上车速上边界 1030、浓度上边界 1.300，合格。
101	        OrderView executed = service.execute(applied.orderNo(), new ExecuteOrderRequest(
