    void clean() {
        cleanBusinessTables(jdbc);
    }

    @Test
    @DisplayName("并发执行中调整同一订单：唯一受理，其余409，版本链无重复无空洞")
    void concurrentAdjustOnlyOneAccepted() throws Exception {
        String orderNo = prepareExecutedOrderWithRatio("cc-adj-apply", "PM-BC1", "20.000");

