    }

    // ------------------------------------------------------------------
    // 测试辅助
    // ------------------------------------------------------------------

    private String prepareExecutedOrderWithRatio(String requestId, String machine, String ratio) {
        OrderView applied = transitionService.apply(new ApplyOrderRequest(
